# ① 用推导式重建（推荐）
nums = [x for x in nums if x != 2]

# ② 遍历键的快照
for k in list(d):
    if d[k] < 3:
        del d[k]
# 或同样用推导式重建
d = {k: v for k, v in d.items() if v >= 3}

from collections import Counter

def is_anagram(s, t):
    if len(s) != len(t):
        return False
    return Counter(s) == Counter(t)

# 手写 dict 版本
def is_anagram2(s, t):
    if len(s) != len(t):
        return False
    cnt = {}
    for ch in s:
        cnt[ch] = cnt.get(ch, 0) + 1
    for ch in t:
        if ch not in cnt:
            return False
        cnt[ch] -= 1
        if cnt[ch] == 0:
            del cnt[ch]
    return not cnt

print(is_anagram('anagram', 'nagaram'))  # True

def intersection(nums1, nums2):
    return list(set(nums1) & set(nums2))

def intersection_ordered(nums1, nums2):
    s2 = set(nums2)
    return [x for x in dict.fromkeys(nums1) if x in s2]

print(intersection([1, 2, 2, 1], [2, 2]))              # [2]
print(intersection_ordered([4, 9, 5, 9], [9, 4, 9, 8, 4]))  # [4, 9]
